head.script:
scwin.gridView1_onbeforeedit = function(row, col, value, colIndex) {
    log = row;
    log1 = col;
    log2 = value;
    console.log('row', row);
    console.log('col', col);
    console.log('value', value);
    WebSquare.logger.printLog('row' + '=' + row);
    WebSquare.logger.printLog('col' + '=' + col);
    WebSquare.logger.printLog('value' + '=' + value);
};
scwin.fireDbClick = function(node) {
    if (document.createEventObject) {
        node.fireEvent('ondblclick');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('dblclick', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.ondblclick == 'function') {
        node.ondblclick();
    }
}
scwin.Dbclick = function(id) {
    var el = WebSquare.wUnit.getDomById($p.id + id);
    scwin.fireDbClick(el);
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. 샘플파일을 실행 후 gridView 값을 편집하기위해 마우스로 더블클릭한 후 콘솔창 및 로그보기를 확인한다.
    //After running the sample file, double-click the mouse to edit the gridView value and check the console window and log view.
    WebSquare.wUnit.addCommand("set", "scwin.Dbclick($p.id+'gridView1_cell_0_0')");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 1. row인자 값이 row index 값으로 보여지고 col인자 값이 column index값으로 보여진다.(예 : row 0, col 0 , value 1)
    //The row parameter value is displayed as the row index value and the col parameter value is shown as the column index value.(For example, row 0, col 0, value 1)
    WebSquare.wUnit.addCommand("assert", "log == 0", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "log1 == 0", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "log2 == 1", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.log = "";
    window.log1 = "";
    window.log2 = "";
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 29-Jan-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
